reference_solution:
def smallest_different_frequency_pair(nums):
    from collections import Counter
    counts=Counter(nums);values=sorted(counts)
    for first in values:
        for second in values:
            if first!=second and counts[first]!=counts[second]:return [first,second]
    return [-1,-1]

